module minimize_shift(\n    input [1:0] n,\n    input [1:0] m,\n    input [2:0] h,\n    input [11:0] u,\n    input [15:0] clients,\n    output reg [1:0] k,\n    output reg [7:0] list\n);\n    \n    reg valid_mask [0:15];\n    reg [1:0] size [0:15];\n    reg [3:0] mask;\n    reg [1:0] curr_size;\n    reg curr_valid;\n    reg [1:0] min_size;\n    reg [3:0] best_mask;\n    integer i, j;\n    reg [1:0] c1, c2;\n    reg [2:0] time1, time2;\n    reg [2:0] new_time1, new_time2;\n\n    function automatic [2:0] shift_time;\n        input [2:0] orig_time;\n        input [2:0] h_val;\n        begin\n            shift_time = (orig_time + 3'd1) % h_val;\n        end\n    endfunction\n\n    function automatic [1:0] popcount;\n        input [3:0] val;\n        integer b;\n        begin\n            popcount = 0;\n            for (b = 0; b < 4; b = b + 1)\n                popcount = popcount + val[b];\n        end\n    endfunction\n\n    always @(*) begin\n        min_size = 2'd4;\n        best_mask = 4'b0;\n        \n        for (i = 0; i < 16; i = i + 1) begin\n            valid_mask[i] = 1'b0;\n            size[i] = 2'd0;\n        end\n\n        for (mask = 1; mask < 16; mask = mask + 1) begin\n            if ((mask & ~((4'b0001 << n) - 1)) != 4'b0) continue;\n            curr_valid = 1'b1;\n            curr_size = popcount(mask);\n\n            for (j = 0; j < m; j = j + 1) begin\n                c1 = clients[j*4 +: 2];\n                c2 = clients[j*4 + 2 +: 2];\n\n                time1 = u[(c1-1)*3 +: 3];\n                time2 = u[(c2-1)*3 +: 3];\n\n                new_time1 = mask[c1-1] ? shift_time(time1, h) : time1;\n                new_time2 = mask[c2-1] ? shift_time(time2, h) : time2;\n\n                if (new_time1 == new_time2) begin\n                    curr_valid = 1'b0;\n                end\n            end\n\n            if (curr_valid) begin\n                valid_mask[mask] = 1'b1;\n                size[mask] = curr_size;\n\n                if (curr_size < min_size) begin\n                    min_size = curr_size;\n                    best_mask = mask;\n                end\n            end\n        end\n\n        k = min_size;\n        list = 8'd0;\n        for (i = 0; i < 4; i = i + 1) begin\n            if (best_mask[i]) begin\n                list = list | ((i + 1) << (k*2 - 2));\n                k = k - 1;\n            end\n        end\n    end\nendmodule